CREATE FUNCTION public_bot.norm(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT lower(translate(coalesce(t,''),'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC')) $$;
CREATE FUNCTION public_bot.clean(t text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public_bot AS $$
DECLARE result text:=coalesce(t,''); i integer;
BEGIN
 FOR i IN 1..3 LOOP result:=coalesce(public.cordial_site_decode_public_text(result),''); END LOOP;
 result:=regexp_replace(result,'<(script|style)[^>]*>.*?</\1>',' ','gi');
 result:=regexp_replace(result,'<[^>]*>',' ','g');
 result:=regexp_replace(result,'https?://[^[:space:]]+',' ','gi');
 result:=regexp_replace(result,'[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}','[contato removido]','gi');
 result:=regexp_replace(result,'\m[0-9]{3}\.?[0-9]{3}\.?[0-9]{3}-?[0-9]{2}\M','[documento removido]','g');
 result:=regexp_replace(result,'(\+?55[[:space:]]*)?\(?[0-9]{2}\)?[[:space:]]*9?[0-9]{4}[-[:space:]]?[0-9]{4}\M','[contato removido]','g');
 RETURN left(btrim(regexp_replace(result,'[[:space:]]+',' ','g')),12000);
END $$;
CREATE FUNCTION public_bot.feature(d jsonb,n text,s text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public_bot AS $$
DECLARE line text; txt text; st text; found text; evidence text;
BEGIN
 FOR line IN SELECT value FROM jsonb_array_elements_text(coalesce(d->'features','[]')) UNION ALL SELECT regexp_split_to_table(coalesce(d->>'description',''),'[.;\n]') LOOP
  txt:=public_bot.norm(line);
  IF position(n in txt)=0 OR txt ~ 'espaco para|possibilidade|projeto|construir|pode (ter|instalar)|futura|previsao|preparacao|nao informad|ignore|instrucoes|system|prompt|senha|token|proprietario|cpf|comissao' THEN CONTINUE; END IF;
  IF (s='condominium') IS DISTINCT FROM (txt ~ 'condominio|condominial|compartilhad|coletiv') THEN CONTINUE; END IF;
  st:=NULL;
  IF txt ~ ('(sem|nao (tem|possui|conta com)) ([[:alnum:]]+ ){0,2}'||n) THEN st:='absent';
  ELSIF (d->'features') ? line OR txt ~ ('(com|possui|tem|conta com|oferece) ([[:alnum:]]+ ){0,2}'||n||'|'||n||' (privativa|existente|no condominio)') THEN st:='present'; END IF;
  IF st IS NOT NULL THEN
   IF found IS NOT NULL AND found<>st THEN RETURN jsonb_build_object('state','unknown','evidence',NULL); END IF;
   found:=st; evidence:=left(line,200);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('state',coalesce(found,'unknown'),'evidence',evidence);
END $$;
