CREATE FUNCTION public_bot.source(b text, ids uuid[] DEFAULT NULL) RETURNS TABLE(public_id uuid,document jsonb,cover jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
 WITH eligible AS (
 SELECT e.* FROM public.cordial_site_eligible e WHERE b='cordial' AND (ids IS NULL OR e.public_id=ANY(ids))
 UNION ALL SELECT e.* FROM public.morar_site_eligible e WHERE b='morar' AND (ids IS NULL OR e.public_id=ANY(ids))
 ), media AS (
 SELECT m.public_id,m.id,m.version,m.width,m.height,m.position FROM public.cordial_site_authorized_media m WHERE b='cordial' AND (ids IS NULL OR m.public_id=ANY(ids))
 UNION ALL SELECT m.public_id,m.id,m.version,m.width,m.height,m.position FROM public.morar_site_authorized_media m WHERE b='morar' AND (ids IS NULL OR m.public_id=ANY(ids))
 ) SELECT e.public_id,jsonb_build_object('id',e.public_id,'reference',e.public_reference,'operation',e.operacao,'type',e.tipo,'city',e.cidade,'district',e.bairro,'price',e.valor,'priceMode',e.valor_modo,'bedrooms',e.dormitorios,'bathrooms',e.banheiros,'suites',e.suites,'parking',e.vagas,'areas',jsonb_build_object('util',e.area_util,'total',e.area_total,'construida',e.area_construida,'terreno',e.area_terreno),'furnished',e.mobiliado,'exchange',e.permuta,'financing',e.aceita_financiamento,'stage',e.estagio_empreendimento,'description',public_bot.clean(e.descricao_imovel),'features',coalesce((SELECT jsonb_agg(left(public_bot.clean(x),200)) FROM (SELECT unnest(e.caracteristicas) LIMIT 100) f(x)),'[]'::jsonb)),
 (SELECT jsonb_build_object('id',m.id,'version',m.version,'width',m.width,'height',m.height,'position',m.position) FROM media m WHERE m.public_id=e.public_id ORDER BY m.position,m.id LIMIT 1)
 FROM eligible e
$$;
CREATE FUNCTION public_bot.refresh_property(pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE b text; ids uuid[]; row record; ver text; n text; s text; feature jsonb;
BEGIN
 FOREACH b IN ARRAY ARRAY['cordial','morar'] LOOP
  SELECT array_agg(p.public_id) INTO ids FROM (
   SELECT p.public_id FROM public.cordial_site_publications p WHERE b='cordial' AND p.property_id=pid
   UNION ALL SELECT p.public_id FROM public.morar_site_publications p WHERE b='morar' AND p.property_id=pid
  ) p;
  IF ids IS NULL THEN CONTINUE; END IF;
  DELETE FROM public_bot.search_documents d WHERE d.brand=b AND d.public_id=ANY(ids) AND NOT EXISTS(SELECT 1 FROM public_bot.source(b,ids) s WHERE s.public_id=d.public_id);
  FOR row IN SELECT * FROM public_bot.source(b,ids) LOOP
   ver:=md5(row.document::text||coalesce(row.cover::text,''));
   INSERT INTO public_bot.search_documents(brand,public_id,source_version,document,cover,operation,city,district,type,price,search_text)
   VALUES(b,row.public_id,ver,row.document,row.cover,row.document->>'operation',public_bot.norm(row.document->>'city'),public_bot.norm(row.document->>'district'),public_bot.norm(row.document->>'type'),(row.document->>'price')::numeric,to_tsvector('portuguese',row.document::text))
   ON CONFLICT(brand,public_id) DO UPDATE SET source_version=excluded.source_version,document=excluded.document,cover=excluded.cover,operation=excluded.operation,city=excluded.city,district=excluded.district,type=excluded.type,price=excluded.price,search_text=excluded.search_text,updated_at=now() WHERE search_documents.source_version<>excluded.source_version;
   FOREACH n IN ARRAY ARRAY['piscina','churrasqueira','sala','cozinha'] LOOP FOREACH s IN ARRAY ARRAY['private','condominium'] LOOP
    feature:=public_bot.feature(row.document,n,s);
    INSERT INTO public_bot.search_features VALUES(b,row.public_id,n,s,feature->>'state',feature->>'evidence',ver)
    ON CONFLICT(brand,public_id,name,scope) DO UPDATE SET state=excluded.state,evidence=excluded.evidence,source_version=excluded.source_version WHERE search_features.source_version<>excluded.source_version;
   END LOOP; END LOOP;
  END LOOP;
 END LOOP;
END $$;
CREATE FUNCTION public_bot.sync_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE j jsonb; oldj jsonb; pid uuid; oldpid uuid;
BEGIN
 j:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 pid:=CASE WHEN TG_TABLE_NAME='properties' THEN (j->>'id')::uuid ELSE (j->>'property_id')::uuid END;
 IF pid IS NULL AND j ? 'image_id' THEN SELECT property_id INTO pid FROM public.property_images WHERE id=(j->>'image_id')::uuid; END IF;
 IF TG_OP='DELETE' AND TG_TABLE_NAME IN ('cordial_site_publications','morar_site_publications') THEN DELETE FROM public_bot.search_documents WHERE brand=CASE WHEN TG_TABLE_NAME='cordial_site_publications' THEN 'cordial' ELSE 'morar' END AND public_id=(j->>'public_id')::uuid; END IF;
 IF TG_OP='UPDATE' THEN
  oldj:=to_jsonb(OLD); oldpid:=CASE WHEN TG_TABLE_NAME='properties' THEN (oldj->>'id')::uuid ELSE (oldj->>'property_id')::uuid END;
  IF oldpid IS NULL AND oldj ? 'image_id' THEN SELECT property_id INTO oldpid FROM public.property_images WHERE id=(oldj->>'image_id')::uuid; END IF;
  IF oldpid IS DISTINCT FROM pid AND oldpid IS NOT NULL THEN PERFORM public_bot.refresh_property(oldpid); END IF;
  IF TG_TABLE_NAME IN ('cordial_site_publications','morar_site_publications') AND oldj->>'public_id' IS DISTINCT FROM j->>'public_id' THEN DELETE FROM public_bot.search_documents WHERE brand=CASE WHEN TG_TABLE_NAME='cordial_site_publications' THEN 'cordial' ELSE 'morar' END AND public_id=(oldj->>'public_id')::uuid; END IF;
 END IF;
 IF pid IS NOT NULL THEN PERFORM public_bot.refresh_property(pid); END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER zz_public_bot_properties AFTER INSERT OR UPDATE OR DELETE ON public.properties DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
CREATE CONSTRAINT TRIGGER zz_public_bot_cordial AFTER INSERT OR UPDATE OR DELETE ON public.cordial_site_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
CREATE CONSTRAINT TRIGGER zz_public_bot_morar AFTER INSERT OR UPDATE OR DELETE ON public.morar_site_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
CREATE CONSTRAINT TRIGGER zz_public_bot_images AFTER INSERT OR UPDATE OR DELETE ON public.property_images DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
CREATE CONSTRAINT TRIGGER zz_public_bot_cordial_media AFTER INSERT OR UPDATE OR DELETE ON public.cordial_site_media DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
CREATE CONSTRAINT TRIGGER zz_public_bot_morar_media AFTER INSERT OR UPDATE OR DELETE ON public.morar_site_media DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public_bot.sync_trigger();
