CREATE FUNCTION public_bot.valid_range(f jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE bound jsonb; k text;
BEGIN
 IF f IS NULL OR f='null'::jsonb THEN RETURN true; END IF;
 IF jsonb_typeof(f)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) x WHERE x NOT IN ('min','max')) THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['min','max'] LOOP
  bound:=f->k;
  IF bound IS NULL OR bound='null'::jsonb THEN CONTINUE; END IF;
  IF jsonb_typeof(bound)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(bound))<>2 OR NOT bound ?& ARRAY['value','inclusive'] OR jsonb_typeof(bound->'value')<>'number' OR jsonb_typeof(bound->'inclusive')<>'boolean' OR (bound->>'value')::numeric NOT BETWEEN 0 AND 1e12 THEN RETURN false; END IF;
 END LOOP;
 IF f->>'min' IS NOT NULL AND f->>'max' IS NOT NULL AND ((f->'min'->>'value')::numeric>(f->'max'->>'value')::numeric OR ((f->'min'->>'value')::numeric=(f->'max'->>'value')::numeric AND NOT ((f->'min'->>'inclusive')::boolean AND (f->'max'->>'inclusive')::boolean))) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION public_bot.valid_filters(f jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public_bot AS $$
DECLARE k text; v jsonb;
BEGIN
 IF f IS NULL OR jsonb_typeof(f)<>'object' OR pg_column_size(f)>8000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) x WHERE x NOT IN ('operation','type','city','district','reference','budget','bedrooms','bathrooms','suites','parking','area','furnished','financing','exchange','stage','features')) THEN RETURN false; END IF;
 IF f->>'operation' IS NOT NULL AND f->>'operation' NOT IN ('venda','aluguel') THEN RETURN false; END IF;
 FOREACH k IN ARRAY ARRAY['type','city','district','reference','stage'] LOOP IF f->>k IS NOT NULL AND (jsonb_typeof(f->k)<>'string' OR length(f->>k) NOT BETWEEN 1 AND 100) THEN RETURN false; END IF; END LOOP;
 FOREACH k IN ARRAY ARRAY['furnished','financing','exchange'] LOOP IF f->>k IS NOT NULL AND jsonb_typeof(f->k)<>'boolean' THEN RETURN false; END IF; END LOOP;
 FOREACH k IN ARRAY ARRAY['bedrooms','bathrooms','suites','parking'] LOOP
  v:=f->k; IF v IS NULL OR v='null'::jsonb THEN CONTINUE; END IF;
  IF jsonb_typeof(v)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>2 OR NOT v ?& ARRAY['op','value'] OR v->>'op' NOT IN ('eq','gt','gte','lt','lte') OR jsonb_typeof(v->'value')<>'number' OR (v->>'value')::numeric NOT BETWEEN 0 AND 100 OR (v->>'value')::numeric<>trunc((v->>'value')::numeric) THEN RETURN false; END IF;
 END LOOP;
 IF NOT public_bot.valid_range(f->'budget') THEN RETURN false; END IF;
 v:=f->'area';
 IF v IS NOT NULL AND v<>'null'::jsonb AND (jsonb_typeof(v)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>2 OR NOT v ?& ARRAY['kind','range'] OR v->>'kind' NOT IN ('util','total','construida','terreno') OR NOT public_bot.valid_range(v->'range')) THEN RETURN false; END IF;
 IF f ? 'features' THEN
  IF jsonb_typeof(f->'features')<>'array' OR jsonb_array_length(f->'features')>8 THEN RETURN false; END IF;
  FOR v IN SELECT value FROM jsonb_array_elements(f->'features') LOOP
   IF jsonb_typeof(v)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>4 OR NOT v ?& ARRAY['name','scope','state','required'] OR v->>'name' NOT IN ('piscina','churrasqueira','sala','cozinha') OR v->>'scope' NOT IN ('private','condominium') OR v->>'state' NOT IN ('present','absent') OR jsonb_typeof(v->'required')<>'boolean' THEN RETURN false; END IF;
  END LOOP;
 END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION public_bot.valid_draft(d jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public_bot AS $$
 SELECT coalesce(jsonb_typeof(d)='object' AND (SELECT count(*) FROM jsonb_object_keys(d))=4 AND d ?& ARRAY['revision','filters','countsAnswered','budgetAnswered'] AND jsonb_typeof(d->'revision')='number' AND (d->>'revision')::numeric BETWEEN 0 AND 100000 AND (d->>'revision')::numeric=trunc((d->>'revision')::numeric) AND jsonb_typeof(d->'countsAnswered')='boolean' AND jsonb_typeof(d->'budgetAnswered')='boolean' AND public_bot.valid_filters(d->'filters') AND (SELECT count(*) FROM jsonb_object_keys(d->'filters'))=16,false)
$$;
CREATE FUNCTION public_bot.range_match(v numeric,f jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT f IS NULL OR f='null'::jsonb OR v IS NOT NULL AND
 (f->'min' IS NULL OR f->'min'='null'::jsonb OR CASE WHEN (f->'min'->>'inclusive')::boolean THEN v >= (f->'min'->>'value')::numeric ELSE v > (f->'min'->>'value')::numeric END) AND
 (f->'max' IS NULL OR f->'max'='null'::jsonb OR CASE WHEN (f->'max'->>'inclusive')::boolean THEN v <= (f->'max'->>'value')::numeric ELSE v < (f->'max'->>'value')::numeric END)
$$;
CREATE FUNCTION public_bot.count_match(v numeric,f jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT f IS NULL OR f='null'::jsonb OR v IS NOT NULL AND CASE f->>'op' WHEN 'eq' THEN v=(f->>'value')::numeric WHEN 'gte' THEN v>=(f->>'value')::numeric WHEN 'gt' THEN v>(f->>'value')::numeric WHEN 'lte' THEN v<=(f->>'value')::numeric WHEN 'lt' THEN v<(f->>'value')::numeric ELSE false END $$;
CREATE FUNCTION public_bot.resolve(b text,ids uuid[]) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('brand',b,'version',d.source_version,'property',s.document,'cover',s.cover) ORDER BY array_position(ids,s.public_id)),'[]'::jsonb)
 FROM public_bot.source(b,ids) s JOIN public_bot.search_documents d ON d.brand=b AND d.public_id=s.public_id AND d.source_version=md5(s.document::text||coalesce(s.cover::text,''))
 WHERE cardinality(ids)<=200
$$;
CREATE FUNCTION public_bot.candidates(b text,f jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
 WITH matches AS (SELECT d.public_id,
  (SELECT count(*) FROM jsonb_array_elements(coalesce(f->'features','[]')) x WHERE coalesce((x->>'required')::boolean,true)=false AND public_bot.feature(d.document,x->>'name',x->>'scope')->>'state' IS DISTINCT FROM x->>'state') AS differences
 FROM public_bot.search_documents d WHERE d.brand=b AND public_bot.valid_filters(f)
 AND (f->>'operation' IS NULL OR d.operation=f->>'operation') AND (f->>'type' IS NULL OR d.type=public_bot.norm(f->>'type')) AND (f->>'city' IS NULL OR d.city=public_bot.norm(f->>'city')) AND (f->>'district' IS NULL OR d.district=public_bot.norm(f->>'district'))
 AND (f->>'reference' IS NULL OR public_bot.norm(d.document->>'reference')=public_bot.norm(f->>'reference')) AND (f->>'stage' IS NULL OR public_bot.norm(d.document->>'stage')=public_bot.norm(f->>'stage'))
 AND (f->'budget' IS NULL OR f->'budget'='null'::jsonb OR d.document->>'priceMode'='fixo' AND public_bot.range_match(d.price,f->'budget'))
 AND public_bot.count_match((d.document->>'bedrooms')::numeric,f->'bedrooms') AND public_bot.count_match((d.document->>'bathrooms')::numeric,f->'bathrooms') AND public_bot.count_match((d.document->>'suites')::numeric,f->'suites') AND public_bot.count_match((d.document->>'parking')::numeric,f->'parking')
 AND (f->>'furnished' IS NULL OR d.document->>'furnished'=f->>'furnished') AND (f->>'exchange' IS NULL OR d.document->>'exchange'=f->>'exchange') AND (f->>'financing' IS NULL OR d.document->>'financing'=f->>'financing')
 AND (f->'area' IS NULL OR f->'area'='null'::jsonb OR public_bot.range_match((d.document->'areas'->>(f->'area'->>'kind'))::numeric,f->'area'->'range'))
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(f->'features','[]')) x WHERE coalesce((x->>'required')::boolean,true) AND public_bot.feature(d.document,x->>'name',x->>'scope')->>'state' IS DISTINCT FROM x->>'state')
 ORDER BY differences,d.public_id LIMIT 30)
 SELECT public_bot.resolve(b,coalesce(array_agg(public_id ORDER BY differences,public_id),'{}'::uuid[])) FROM matches
$$;
CREATE FUNCTION public_bot.facets(b text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
 SELECT jsonb_build_object('types',coalesce(jsonb_agg(DISTINCT document->>'type') FILTER(WHERE document->>'type' IS NOT NULL),'[]'), 'cities',coalesce(jsonb_agg(DISTINCT document->>'city') FILTER(WHERE document->>'city' IS NOT NULL),'[]'),'districts',coalesce(jsonb_agg(DISTINCT jsonb_build_object('city',document->>'city','district',document->>'district')) FILTER(WHERE document->>'city' IS NOT NULL AND document->>'district' IS NOT NULL),'[]'),'version',md5(coalesce(string_agg(source_version,',' ORDER BY public_id),''))) FROM public_bot.search_documents WHERE brand=b
$$;
CREATE FUNCTION public_bot.configuration(b text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
 SELECT jsonb_build_object('enabled',c.enabled,'voice',c.voice,'trends',c.trends,'whatsapp',coalesce((CASE WHEN b='cordial' THEN (SELECT content->>'whatsapp' FROM public.cordial_site_settings WHERE id) ELSE (SELECT content->>'whatsapp' FROM public.morar_site_settings WHERE id) END),'')) FROM public_bot.configuration_data c WHERE brand=b
$$;
CREATE FUNCTION public_bot.empty_draft() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT '{"revision":0,"countsAnswered":false,"budgetAnswered":false,"filters":{"operation":null,"type":null,"city":null,"district":null,"reference":null,"budget":null,"bedrooms":null,"bathrooms":null,"suites":null,"parking":null,"area":null,"furnished":null,"financing":null,"exchange":null,"stage":null,"features":[]}}'::jsonb $$;
CREATE FUNCTION public_bot.open_session(b text,token_hash text,ip_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; n integer;
BEGIN
 IF coalesce(b,'') NOT IN ('cordial','morar') OR coalesce(token_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(ip_key,'') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid' USING ERRCODE='22023'; END IF;
 INSERT INTO public_bot.open_limits VALUES(ip_key,now(),1) ON CONFLICT ON CONSTRAINT open_limits_pkey DO UPDATE SET attempts=CASE WHEN open_limits.window_at<now()-interval '1 minute' THEN 1 ELSE open_limits.attempts+1 END, window_at=CASE WHEN open_limits.window_at<now()-interval '1 minute' THEN now() ELSE open_limits.window_at END RETURNING attempts INTO n;
 IF n>10 THEN RETURN '{"code":"burst"}'; END IF;
 DELETE FROM public_bot.sessions WHERE sessions.brand=b AND sessions.token_hash=token_hash AND (expires_at<now() OR created_at<now()-interval '7 days');
 INSERT INTO public_bot.sessions(brand,token_hash,draft) VALUES(b,token_hash,public_bot.empty_draft()) ON CONFLICT ON CONSTRAINT sessions_brand_token_hash_key DO UPDATE SET last_used=now(),expires_at=least(sessions.created_at+interval '7 days',now()+interval '24 hours') RETURNING * INTO s;
 RETURN jsonb_build_object('id',s.id,'draft',s.draft,'turns',coalesce((SELECT jsonb_agg(jsonb_build_object('requestId',t.request_id,'answer',t.result->>'answer','ids',t.ids) ORDER BY t.created_at) FROM (SELECT * FROM public_bot.turns r WHERE r.session_id=s.id AND r.state='completed' ORDER BY r.created_at DESC LIMIT 25) t),'[]'));
END $$;
CREATE FUNCTION public_bot.accept_turn(b text,token_hash text,ip_key text,local_day date,request_id uuid,expected_revision integer,fingerprint text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; t public_bot.turns; q public_bot.daily_quotas; result jsonb;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash AND x.expires_at>now() AND x.created_at>now()-interval '7 days' FOR UPDATE;
 IF s.id IS NULL OR request_id IS NULL OR expected_revision IS NULL OR local_day IS DISTINCT FROM (now() AT TIME ZONE 'America/Sao_Paulo')::date OR coalesce(ip_key,'') !~ '^[a-f0-9]{64}$' OR coalesce(fingerprint,'') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO t FROM public_bot.turns x WHERE x.session_id=s.id AND x.request_id=request_id;
 IF t.request_id IS NOT NULL THEN
  IF t.fingerprint<>fingerprint THEN RAISE EXCEPTION 'request_conflict' USING ERRCODE='22023'; END IF;
  IF t.state='completed' THEN RETURN jsonb_build_object('state','replay','draft',s.draft,'result',t.result||jsonb_build_object('ids',t.ids),'exhausted',coalesce((t.result->>'exhausted')::boolean,false)); END IF;
  IF s.active_request IS DISTINCT FROM request_id OR s.lease_until IS NULL OR s.lease_until<now() OR t.state='interrupted' THEN UPDATE public_bot.turns SET state='interrupted' WHERE session_id=s.id AND turns.request_id=request_id; UPDATE public_bot.sessions SET active_request=NULL,lease_until=NULL WHERE id=s.id AND active_request=request_id; RETURN jsonb_build_object('state','interrupted','draft',s.draft,'exhausted',false); END IF;
  RETURN jsonb_build_object('state','busy','draft',s.draft,'exhausted',false);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public_bot.configuration_data WHERE brand=b AND enabled) THEN RETURN jsonb_build_object('state','interrupted','draft',s.draft,'exhausted',false); END IF;
 IF (s.draft->>'revision')::integer<>expected_revision THEN RETURN jsonb_build_object('state','stale','draft',s.draft,'exhausted',false); END IF;
 IF s.active_request IS NOT NULL AND s.lease_until>now() THEN RETURN jsonb_build_object('state','busy','draft',s.draft,'exhausted',false); END IF;
 INSERT INTO public_bot.daily_quotas(ip_key,local_day) VALUES(ip_key,local_day) ON CONFLICT DO NOTHING;
 SELECT * INTO q FROM public_bot.daily_quotas x WHERE x.ip_key=ip_key AND x.local_day=local_day FOR UPDATE;
 IF q.accepted>=25 THEN RETURN jsonb_build_object('state','exhausted','draft',s.draft,'exhausted',true); END IF;
 IF q.minute_at>now()-interval '1 minute' AND q.minute_count>=6 THEN RETURN jsonb_build_object('state','burst','draft',s.draft,'exhausted',false); END IF;
 UPDATE public_bot.daily_quotas x SET accepted=x.accepted+1,minute_count=CASE WHEN x.minute_at<now()-interval '1 minute' THEN 1 ELSE x.minute_count+1 END,minute_at=CASE WHEN x.minute_at<now()-interval '1 minute' THEN now() ELSE x.minute_at END WHERE x.ip_key=ip_key AND x.local_day=local_day;
 UPDATE public_bot.turns SET state='interrupted' WHERE session_id=s.id AND state='accepted';
 INSERT INTO public_bot.turns(session_id,request_id,fingerprint,state) VALUES(s.id,request_id,fingerprint,'accepted');
 UPDATE public_bot.sessions SET active_request=request_id,lease_until=now()+interval '30 seconds',last_used=now(),expires_at=least(created_at+interval '7 days',now()+interval '24 hours') WHERE id=s.id;
 RETURN jsonb_build_object('state','accepted','draft',s.draft,'exhausted',q.accepted=24);
END $$;
CREATE FUNCTION public_bot.complete_turn(b text,token_hash text,request_id uuid,result jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash FOR UPDATE;
 IF s.id IS NULL OR s.expires_at<now() OR s.created_at<now()-interval '7 days' OR s.active_request IS DISTINCT FROM request_id OR s.lease_until IS NULL OR s.lease_until<now() OR (result->'draft'->>'revision')::int IS DISTINCT FROM (s.draft->>'revision')::int+1 OR NOT public_bot.valid_draft(result->'draft') OR result->>'requestId' IS DISTINCT FROM request_id::text OR jsonb_typeof(result->'cards') IS DISTINCT FROM 'array' OR jsonb_array_length(result->'cards')>5 OR jsonb_typeof(result->'answer') IS DISTINCT FROM 'string' OR length(result->>'answer')>800 OR jsonb_typeof(result->'exhausted') IS DISTINCT FROM 'boolean' OR jsonb_typeof(result->'unavailable') IS DISTINCT FROM 'boolean' OR EXISTS(SELECT 1 FROM jsonb_object_keys(result) k WHERE k NOT IN ('requestId','draft','answer','cards','question','exhausted','unavailable')) OR pg_column_size(result)>20000 THEN RETURN false; END IF;
 UPDATE public_bot.turns SET state='completed',result=result-'cards',ids=coalesce((SELECT jsonb_agg(x->'id') FROM jsonb_array_elements(result->'cards') x),'[]') WHERE session_id=s.id AND turns.request_id=request_id AND state='accepted';
 UPDATE public_bot.sessions SET draft=result->'draft',active_request=NULL,lease_until=NULL WHERE id=s.id;
 RETURN true;
END $$;
CREATE FUNCTION public_bot.reserve_cost(b text,token_hash text,request_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; t public_bot.turns; c public_bot.configuration_data; g public_bot.global_usage; d date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash FOR UPDATE;
 SELECT * INTO t FROM public_bot.turns x WHERE x.session_id=s.id AND x.request_id=request_id FOR UPDATE;
 IF t.state IS DISTINCT FROM 'accepted' OR t.paid_started OR s.active_request IS DISTINCT FROM request_id OR s.lease_until IS NULL OR s.lease_until<now() THEN RETURN false; END IF;
 SELECT * INTO c FROM public_bot.configuration_data WHERE brand=b;
 IF NOT coalesce(c.enabled,false) THEN RETURN false; END IF;
 INSERT INTO public_bot.global_usage(local_day) VALUES(d) ON CONFLICT DO NOTHING;
 SELECT * INTO g FROM public_bot.global_usage WHERE global_usage.local_day=d FOR UPDATE;
 IF g.paid_calls>=(SELECT min(daily_paid_limit) FROM public_bot.configuration_data) OR g.reserved_micros+c.reserve_micros>(SELECT min(daily_cost_micros) FROM public_bot.configuration_data) OR (SELECT count(*) FROM public_bot.sessions WHERE lease_until>now() AND active_request IS NOT NULL)>20 THEN RETURN false; END IF;
 UPDATE public_bot.global_usage SET paid_calls=paid_calls+1,reserved_micros=reserved_micros+c.reserve_micros WHERE global_usage.local_day=d;
 UPDATE public_bot.turns SET paid_started=true WHERE session_id=s.id AND turns.request_id=request_id;
 RETURN true;
END $$;
