CREATE FUNCTION public_bot.read_session(b text,token_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash AND x.expires_at>now() AND x.created_at>now()-interval '7 days';
 IF s.id IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('id',s.id,'draft',s.draft,'turns',coalesce((SELECT jsonb_agg(jsonb_build_object('requestId',t.request_id,'answer',t.result->>'answer','ids',t.ids) ORDER BY t.created_at) FROM (SELECT * FROM public_bot.turns r WHERE r.session_id=s.id AND r.state='completed' ORDER BY r.created_at DESC LIMIT 25) t),'[]'));
END $$;
CREATE FUNCTION public_bot.expire_voice(sid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
DECLARE v public_bot.voice_requests;
BEGIN
 FOR v IN SELECT * FROM public_bot.voice_requests WHERE session_id=sid AND state='accepted' AND lease_until<now() FOR UPDATE LOOP
  UPDATE public_bot.daily_quotas SET voice_reserved=greatest(0,voice_reserved-1) WHERE ip_key=v.ip_key AND local_day=v.local_day;
  UPDATE public_bot.voice_requests SET state='interrupted' WHERE session_id=sid AND request_id=v.request_id;
  UPDATE public_bot.sessions SET active_request=NULL,lease_until=NULL WHERE id=sid AND active_request=v.request_id;
 END LOOP;
END $$;
CREATE FUNCTION public_bot.take_voice(b text,token_hash text,ip_key text,local_day date,request_id uuid,bytes integer,seconds integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; q public_bot.daily_quotas; v public_bot.voice_requests; c public_bot.configuration_data; g public_bot.global_usage;
BEGIN
 IF coalesce(b,'') NOT IN ('cordial','morar') OR coalesce(token_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(ip_key,'') !~ '^[a-f0-9]{64}$' OR local_day IS DISTINCT FROM (now() AT TIME ZONE 'America/Sao_Paulo')::date OR bytes NOT BETWEEN 64 AND 10485760 OR seconds NOT BETWEEN 1 AND 60 OR request_id IS NULL OR bytes IS NULL OR seconds IS NULL THEN RAISE EXCEPTION 'invalid_voice' USING ERRCODE='22023'; END IF;
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash AND x.expires_at>now() AND x.created_at>now()-interval '7 days' FOR UPDATE;
 IF s.id IS NULL THEN RETURN '{"state":"interrupted"}'; END IF;
 PERFORM public_bot.expire_voice(s.id);
 SELECT * INTO v FROM public_bot.voice_requests x WHERE x.session_id=s.id AND x.request_id=request_id;
 -- The audio/transcript is intentionally not retained. A retry never incurs another paid call.
 IF v.request_id IS NOT NULL THEN RETURN jsonb_build_object('state',CASE WHEN v.state='accepted' AND v.lease_until>now() THEN 'busy' ELSE 'interrupted' END); END IF;
 SELECT * INTO c FROM public_bot.configuration_data WHERE brand=b;
 IF NOT coalesce(c.enabled AND c.voice,false) THEN RETURN '{"state":"unavailable"}'; END IF;
 IF s.active_request IS NOT NULL AND s.lease_until>now() THEN RETURN '{"state":"busy"}'; END IF;
 INSERT INTO public_bot.daily_quotas(ip_key,local_day) VALUES(ip_key,local_day) ON CONFLICT DO NOTHING;
 SELECT * INTO q FROM public_bot.daily_quotas x WHERE x.ip_key=ip_key AND x.local_day=local_day FOR UPDATE;
 IF q.voices+q.voice_reserved>=25 OR q.voice_attempts>=40 OR q.voice_seconds+seconds>2400 THEN RETURN '{"state":"exhausted"}'; END IF;
 IF q.voice_minute_at>now()-interval '1 minute' AND (q.voice_minute_count>=3 OR q.minute_bytes+bytes>15728640) THEN RETURN '{"state":"burst"}'; END IF;
 INSERT INTO public_bot.global_usage(local_day) VALUES(local_day) ON CONFLICT DO NOTHING;
 SELECT * INTO g FROM public_bot.global_usage x WHERE x.local_day=local_day FOR UPDATE;
 IF g.paid_calls>=(SELECT min(daily_paid_limit) FROM public_bot.configuration_data) OR g.reserved_micros+c.reserve_micros>(SELECT min(daily_cost_micros) FROM public_bot.configuration_data) OR (SELECT count(*) FROM public_bot.sessions WHERE active_request IS NOT NULL AND lease_until>now())>=20 THEN RETURN '{"state":"unavailable"}'; END IF;
 UPDATE public_bot.global_usage x SET paid_calls=x.paid_calls+1,reserved_micros=x.reserved_micros+c.reserve_micros WHERE x.local_day=local_day;
 UPDATE public_bot.daily_quotas x SET voice_reserved=x.voice_reserved+1,voice_attempts=x.voice_attempts+1,voice_seconds=x.voice_seconds+seconds,
  voice_minute_count=CASE WHEN x.voice_minute_at<now()-interval '1 minute' THEN 1 ELSE x.voice_minute_count+1 END,
  minute_bytes=CASE WHEN x.voice_minute_at<now()-interval '1 minute' THEN bytes ELSE x.minute_bytes+bytes END,
  voice_minute_at=CASE WHEN x.voice_minute_at<now()-interval '1 minute' THEN now() ELSE x.voice_minute_at END WHERE x.ip_key=ip_key AND x.local_day=local_day;
 INSERT INTO public_bot.voice_requests(session_id,request_id,ip_key,local_day,state,lease_until) VALUES(s.id,request_id,ip_key,local_day,'accepted',now()+interval '90 seconds');
 UPDATE public_bot.sessions SET active_request=request_id,lease_until=now()+interval '90 seconds',last_used=now(),expires_at=least(created_at+interval '7 days',now()+interval '24 hours') WHERE id=s.id;
 RETURN '{"state":"accepted"}';
END $$;
CREATE FUNCTION public_bot.finish_voice(b text,token_hash text,request_id uuid,ok boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
DECLARE s public_bot.sessions; v public_bot.voice_requests;
BEGIN
 SELECT * INTO s FROM public_bot.sessions x WHERE x.brand=b AND x.token_hash=token_hash FOR UPDATE;
 SELECT * INTO v FROM public_bot.voice_requests x WHERE x.session_id=s.id AND x.request_id=request_id FOR UPDATE;
 IF v.state IS DISTINCT FROM 'accepted' THEN RETURN false; END IF;
 UPDATE public_bot.voice_requests x SET state=CASE WHEN ok AND v.lease_until>=now() THEN 'completed' ELSE 'failed' END WHERE x.session_id=s.id AND x.request_id=request_id;
 UPDATE public_bot.daily_quotas x SET voice_reserved=greatest(0,x.voice_reserved-1),voices=x.voices+CASE WHEN ok AND v.lease_until>=now() THEN 1 ELSE 0 END WHERE x.ip_key=v.ip_key AND x.local_day=v.local_day;
 UPDATE public_bot.sessions SET active_request=NULL,lease_until=NULL WHERE id=s.id AND active_request=request_id;
 RETURN true;
END $$;
CREATE FUNCTION public_bot.usage(b text,request_id uuid,model text,latency integer,input_tokens integer,output_tokens integer,code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public_bot AS $$
#variable_conflict use_variable
BEGIN
 IF b NOT IN ('cordial','morar') OR request_id IS NULL OR model !~ '^[a-zA-Z0-9/_:.\-]{1,100}$' OR code !~ '^[a-z_]{1,40}$' OR latency NOT BETWEEN 0 AND 120000 OR input_tokens NOT BETWEEN 0 AND 1000000 OR output_tokens NOT BETWEEN 0 AND 1000000 THEN RETURN false; END IF;
 INSERT INTO public_bot.usage_data(brand,request_id,model,latency,input_tokens,output_tokens,code) VALUES(b,request_id,model,latency,input_tokens,output_tokens,code) ON CONFLICT ON CONSTRAINT usage_data_brand_request_id_key DO NOTHING;
 RETURN true;
END $$;
